# Generated by release/homebrew/formula.sh of the wolfpack repository for each release.
class Wolfpack < Formula
  desc "Statically typed language that compiles to readable TypeScript, Go and Rust"
  homepage "https://github.com/realfamousbae/wolfpack"
  license any_of: ["MIT", "Apache-2.0"]

  # The macOS archive is universal: the same file for both processors.
  on_macos do
    on_arm do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.4.1/wolfpack-macos-universal.tar.gz"
      sha256 "5f19dcca53da8feddfecc91e64bfdc5a43dea7874de17c8104501265ccb86224"
    end
    on_intel do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.4.1/wolfpack-macos-universal.tar.gz"
      sha256 "5f19dcca53da8feddfecc91e64bfdc5a43dea7874de17c8104501265ccb86224"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.4.1/wolfpack-linux-x64.tar.gz"
      sha256 "7a216f9c5c6bf534e88f30fa31f1eacab614373b1dce10bfd93b05d60de406b7"
    end
    on_arm do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.4.1/wolfpack-linux-arm64.tar.gz"
      sha256 "9b33869f05e92d2ab49aa2ff6d98655eb203b06df902f2f41d905d22544e5019"
    end
  end

  def install
    bin.install "wolf"
  end

  def caveats
    <<~EOS
      wolf runs programs in its own VM without other tools (wolf run --vm).
      To build and run them as TypeScript, Go or Rust, install those tools with:
        wolf setup
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/wolf --version")
    system bin/"wolf", "new", "hello"
    assert_equal "Hello, wolfpack!\n", shell_output("cd hello && #{bin}/wolf run --vm")
  end
end
